INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36211, 'Philippians 2:18', 'Philippians', 2, 18, 'نو تاسو هم خوشحاله اوسئ او زما سره په خوشحالۍ کې شریک شئ. تیموتاوس او اپافرودیتوس په هکله مثالونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_18.mp3', '', 1761754199, 1761754199),
(36212, 'Philippians 2:19', 'Philippians', 2, 19, 'زه څښتن عیسی ته هیله‌من یم چې ډېر زر به تیموتاوس درولېږم، ترڅو ستاسو د احوال نه خبر شم، نو خوشحاله به شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_19.mp3', '', 1761754199, 1761754199),
(36213, 'Philippians 2:20', 'Philippians', 2, 20, 'ځکه چې دلته د هغه په شان زما سره بل څوک نشته چې په رښتیا ستاسو په فکر کې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_20.mp3', '', 1761754199, 1761754199),
(36214, 'Philippians 2:21', 'Philippians', 2, 21, 'ځکه چې نور ټول د خپلو ګټو پسې ګرځي، نه د عیسی مسیح پسې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_21.mp3', '', 1761754199, 1761754199),
(36215, 'Philippians 2:22', 'Philippians', 2, 22, 'خو تاسو پوهېږئ چې تیموتاوس خپل لیاقت ثابت کړ چې هغه لکه د یو زوی په شان چې د خپل پلار خدمت کوي، زما سره د زېري په خپرولو کې خدمت کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_22.mp3', '', 1761754199, 1761754199),
(36216, 'Philippians 2:23', 'Philippians', 2, 23, 'نو له دې امله زه هیله لرم چې څنګه زما حال معلوم شي، نو زه به هغه تاسو ته درولېږم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_23.mp3', '', 1761754199, 1761754199),
(36217, 'Philippians 2:24', 'Philippians', 2, 24, 'او زه په څښتن باندې باور لرم چې په خپله به هم زر درشم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_24.mp3', '', 1761754199, 1761754199),
(36218, 'Philippians 2:25', 'Philippians', 2, 25, 'خو اوس ما دا ضروري وګڼله چې زمونږ ورور، د خدمت ملګری او همکار عسکر اپافرودیتوس تاسو ته درولېږم چې هغه ستاسو پیغام رسوونکی دی او تاسو هغه زما د اړتیاوو د پوره کولو دپاره لېږلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_25.mp3', '', 1761754199, 1761754199),
(36219, 'Philippians 2:26', 'Philippians', 2, 26, 'ځکه چې هغه ډېر ارمان لري چې تاسو ټول وویني او هغه خفه دی، ځکه چې تاسو د هغه د ناروغۍ نه خبر شوي وئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_26.mp3', '', 1761754199, 1761754199),
(36220, 'Philippians 2:27', 'Philippians', 2, 27, 'هغه په رښتیا ناروغه ؤ او مرګ ته نژدې ؤ، خو خدای په هغه باندې رحم وکړ او یوازې په هغه نه، بلکې په ما یې هم وکړ چې په ما باندې د غم دپاسه غم رانه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_27.mp3', '', 1761754199, 1761754199),
(36221, 'Philippians 2:28', 'Philippians', 2, 28, 'نو زه ډېر غواړم چې هغه تاسو ته درولېږم چې یوځل بیا د هغه په لیدلو خوشحاله شئ او زما غم هم کم شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_28.mp3', '', 1761754199, 1761754199),
(36222, 'Philippians 2:29', 'Philippians', 2, 29, 'نو هغه ته د څښتن په نوم په ډېرې خوشحالۍ سره هرکلی ووایئ او د هغه په شان خلکو ته درناوی کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_29.mp3', '', 1761754199, 1761754199),
(36223, 'Philippians 2:30', 'Philippians', 2, 30, 'ځکه چې هغه مسیح ته د خدمت په لاره کې مرګ ته نژدې شوی ؤ او هغه خپل ژوند د هغه خدمت دپاره په خطر کې واچاوه چې تاسو زما دپاره ونه کړای شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians2_verse_30.mp3', '', 1761754199, 1761754199),
(36224, 'Revelation 1:1', 'Revelation', 1, 1, 'دا د عیسی مسیح مکاشفه ده چې خدای هغه ته ورکړې وه، ترڅو هغه پېښې چې ډېر زر باید رامنځته شي خپلو خدمتګارانو ته وښایي. هغه دا مکاشفه خپل خدمتګار یوحنا ته د فرښتې د لېږلو په وسیله ښکاره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_1.mp3', '', 1761754199, 1761754199),
(36225, 'Revelation 1:2', 'Revelation', 1, 2, 'یوحنا چې هرڅه لیدلي وو هغه یې بیان کړل چې دا د خدای د کلام او د عیسی مسېح په هکله شاهدي ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_2.mp3', '', 1761754199, 1761754199),
(36226, 'Revelation 1:3', 'Revelation', 1, 3, 'بختور دی هغه څوک چې د دې کتاب پېشګویانې او پیغامونه نورو ته په لوړ اواز لولي او بختور دي هغه خلک چې غوږ ورته نیسي او هغه څه چې لیکل شوي دي عمل ورباندې کوي، ځکه چې هغه وخت نژدې دی چې دا هرڅه به پېښ شي. اوو کلیساګانو ته سلامونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_3.mp3', '', 1761754199, 1761754199),
(36227, 'Revelation 1:4', 'Revelation', 1, 4, 'د یوحنا له خوا هغو اوو کلیساګانو ته چې د اسیا په ولایت کې دي. په تاسو دې د هغه چا له خوا فضل او سلامتي وي چې هغه دی، هغه ؤ او هغه راتلونکی دی او د هغو اوو روحونو له خوا چې د هغه د پاچاهۍ د تخت په مخکې خدمت کوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_4.mp3', '', 1761754199, 1761754199),
(36228, 'Revelation 1:5', 'Revelation', 1, 5, 'او د عیسی مسیح له خوا چې وفادار شاهد دی او لومړنی زېږېدلی دی چې له مړو نه اول راپاڅېده او د نړۍ د ټولو پاچاهانو سردار دی. هغه زمونږ سره مینه کوي او په خپله وینه یې مونږ د خپلو ګناهونو نه خلاص کړي یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_5.mp3', '', 1761754199, 1761754199),
(36229, 'Revelation 1:6', 'Revelation', 1, 6, 'هغه مونږ پاچاهۍ ته ورسولو او زمونږ څخه یې کاهنان جوړ کړل، ترڅو د هغه د خدای یعنې د هغه د پلار خدمت وکړو. د هغه جلال او قدرت دې تل ترتله وي! امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_6.mp3', '', 1761754199, 1761754199),
(36230, 'Revelation 1:7', 'Revelation', 1, 7, 'ګورئ، هغه په ورېځو کې راځي! هرڅوک به یې په خپلو سترګو وویني او حتی هغه خلک به یې هم وویني چې هغه یې په نېزې وواهه او د نړۍ ټول قومونه به په هغه باندې ویر کوي. هو، همداسې به وشي! امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_7.mp3', '', 1761754199, 1761754199),
(36231, 'Revelation 1:8', 'Revelation', 1, 8, 'څښتن خدای وایي: «زه الف او یا یم. چې زه هغه څوک یم چې وم، یم او راتلونکی یم، یعنې مطلق قادر خدای.» یوحنا ته د عیسی مسیح ښکاره کېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_8.mp3', '', 1761754199, 1761754199),
(36232, 'Revelation 1:9', 'Revelation', 1, 9, 'زه ستاسو ورور یوحنا او د عیسی پیرو یم چې په کړاوونو، د خدای په پاچاهۍ او په صبر او زغم کې ستاسو سره شریک یم. زه د خدای د کلام د موعظې او د عیسی په هکله د شاهدۍ د ورکولو په خاطر د پاتموس په نوم جزیرې ته د سزا دپاره ولېږل شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_9.mp3', '', 1761754199, 1761754199),
(36233, 'Revelation 1:10', 'Revelation', 1, 10, 'دا د څښتن ورځ وه او روح القدس زه تر خپلې اغېزې لاندې راوستلم، بیا ما د شا له خوا د سرني په شان یو لوړ اواز واورېد', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_10.mp3', '', 1761754199, 1761754199),
(36234, 'Revelation 1:11', 'Revelation', 1, 11, 'چې ماته یې وویل: «څه چې وینې، هغه په یو کتاب کې ولیکه او هغو اووه کلیساګانو یعنې د افسیس، اسمیرنا، پرګاموم، تیاتیرا، ساردیس، فیلادلفیا او لایودیکیې کلیساګانو ته یې ولېږه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_11.mp3', '', 1761754199, 1761754199),
(36235, 'Revelation 1:12', 'Revelation', 1, 12, 'ما خپل مخ راواړاوه چې ووینم دا څوک دی چې زما سره خبرې کوي. په هغه وخت کې مې د سرو زرو اووه څراغدانونه ولیدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_12.mp3', '', 1761754199, 1761754199),
(36236, 'Revelation 1:13', 'Revelation', 1, 13, 'د هغو څراغدانونو په منځ کې د انسان په شان یو څوک ؤ چې یوه اوږده چپنه یې اغوستې وه او د سرو زرو یوه پټۍ یې د سینې څخه تاوه کړې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_13.mp3', '', 1761754199, 1761754199),
(36237, 'Revelation 1:14', 'Revelation', 1, 14, 'د سر ویښتان یې لکه د سپینې وړۍ یا واورې په شان سپین وو او سترګې یې د اور د لمبو په شان وې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_14.mp3', '', 1761754199, 1761754199),
(36238, 'Revelation 1:15', 'Revelation', 1, 15, 'پښې یې د هغو صیقل شویو برنجو په شان چې په داش کې پاک شوي وي، ځلېدلې او اواز یې لکه د تېزو اوبو د غرهار په شان ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_15.mp3', '', 1761754199, 1761754199),
(36239, 'Revelation 1:16', 'Revelation', 1, 16, 'هغه په خپل ښي لاس کې اووه ستوري نیولي وو او د خولې نه یې دوه‌مخې تېره توره راوتلې وه او مخ یې لکه د تېز لمر په شان ځلېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_16.mp3', '', 1761754199, 1761754199),
(36240, 'Revelation 1:17', 'Revelation', 1, 17, 'کله چې ما هغه ولیده نو زه لکه د مړي په شان د هغه په پښو کې پرېوتلم، خو هغه خپل ښي لاس په ما کېښود او ویې ویل: «مه وېرېږه، زه اول او اخر یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_17.mp3', '', 1761754199, 1761754199),
(36241, 'Revelation 1:18', 'Revelation', 1, 18, 'زه ژوندی یم، زه مړ شوم او اوس تل ترتله ژوندی یم او د مرګ او قبر کیلي‌ګانې زما سره دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_18.mp3', '', 1761754199, 1761754199),
(36242, 'Revelation 1:19', 'Revelation', 1, 19, 'نو څه چې دې لیدلي دي هغه ولیکه، هغه څه چې اوس شته او هغه څه چې وروسته به پېښ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_19.mp3', '', 1761754199, 1761754199),
(36243, 'Revelation 1:20', 'Revelation', 1, 20, 'د هغو اوو ستورو معنی او پټ راز چې تا زما په ښي لاس کې لیدلي دي او د سرو زرو د څراغدانونو معنی دا ده: هغه اووه ستوري د اوو کلیساګانو فرښتې دي او هغه اووه څراغدانونه اووه کلیساګانې دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation1_verse_20.mp3', '', 1761754199, 1761754199),
(36244, 'Ephesians 4:1', 'Ephesians', 4, 1, 'نو زه چې د څښتن په خاطر بندي یم، ستاسو نه غوښتنه کوم چې داسې ژوند وکړئ چې د هغې بلنې وړ وي چې تاسو تر‌لاسه کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_1.mp3', '', 1761754199, 1761754199),
(36245, 'Ephesians 4:2', 'Ephesians', 4, 2, 'تل په عاجزۍ، نرمۍ، صبر او په مینې سره یو بل وزغمئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_2.mp3', '', 1761754199, 1761754199),
(36246, 'Ephesians 4:3', 'Ephesians', 4, 3, 'ډېر کوښښ وکړئ هغه یووالی وساتئ چې روح القدس یې په سوله او سلامتي کې رامنځته کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_3.mp3', '', 1761754199, 1761754199),
(36247, 'Ephesians 4:4', 'Ephesians', 4, 4, 'لکه څنګه چې یو بدن او یو روح القدس دی، نو همداسې یوه هیله ده چې خدای تاسو ورته رابللي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_4.mp3', '', 1761754199, 1761754199),
(36248, 'Ephesians 4:5', 'Ephesians', 4, 5, 'یو څښتن دی، یو ایمان او یو د تعمید غسل،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_5.mp3', '', 1761754199, 1761754199),
(36249, 'Ephesians 4:6', 'Ephesians', 4, 6, 'یو خدای چې د ټولو پلار او د ټولو نه اوچت دی، زمونږ د ټولو په وسیله کار کوي او په ټولو کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_6.mp3', '', 1761754199, 1761754199),
(36250, 'Ephesians 4:7', 'Ephesians', 4, 7, 'خو مونږ هر یو ته د مسیح د سخاوت له مخې یو نعمت راکړل شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_7.mp3', '', 1761754199, 1761754199),
(36251, 'Ephesians 4:8', 'Ephesians', 4, 8, 'له همدې امله لیکل شوي دي: کله چې پورته لوړو ځایونو ته وروخوت، یووړل یې له ځانه سره زیات بندیان او خلکو ته یې ورکړل نعمتونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_8.mp3', '', 1761754199, 1761754199),
(36252, 'Ephesians 4:9', 'Ephesians', 4, 9, 'کله چې وایي: «هغه پورته لوړو ځایونو ته وروخوت» د دې معنی څه ده، ایا معنی یې دا نه ده چې هغه مخکې د ځمکې ډېر ښکته ځای ته کوز شوی ؤ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_9.mp3', '', 1761754199, 1761754199),
(36253, 'Ephesians 4:10', 'Ephesians', 4, 10, 'نو بیا هغه څوک چې ښکته راکوز شو، دا هماغه دی چې د ټولو اسمانونو نه پورته وخوت، ترڅو ټول کاینات د خپل حضور نه ډک کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_10.mp3', '', 1761754199, 1761754199),
(36254, 'Ephesians 4:11', 'Ephesians', 4, 11, 'دا خپله هماغه څوک ؤ چې خلکو ته یې نعمتونه ورکړل چې ځینې یې رسولان، ځینې یې پیغمبران، ځینې یې زېري رسوونکي، ځینې یې شپانه او ښوونکي وټاکل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_11.mp3', '', 1761754199, 1761754199),
(36255, 'Ephesians 4:12', 'Ephesians', 4, 12, 'هغه داسې وکړل ترڅو د خدای خلک د کار او خدمت دپاره تیار کړي، د دې دپاره چې د مسیح بدن ته وده ورکړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_12.mp3', '', 1761754199, 1761754199),
(36256, 'Ephesians 4:13', 'Ephesians', 4, 13, 'ترڅو مونږ ټول هغه یووالی چې په ایمان او د خدای د زوی په پوره پېژندلو کې دی، تر‌لاسه کړو او په ایمان کې بالغان شو او د مسیح په اندازه کامل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_13.mp3', '', 1761754199, 1761754199),
(36257, 'Ephesians 4:14', 'Ephesians', 4, 14, 'نو نور به مونږ ماشومان نه یو چې د څپو په وسیله اخوا دې خوا وغورځول شو او د انساني هر ډول تعلیم د باد په وسیله دلته او هلته یووړل شو او نه به نور د خلکو د چالاکۍ او د ټګۍ نه ډکو دسیسو له امله بې‌لارې کېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_14.mp3', '', 1761754199, 1761754199),
(36258, 'Ephesians 4:15', 'Ephesians', 4, 15, 'نو د دې په ځای مونږ باید په مینه حقیقت ووایو او په هر حال کې په مسیح کې چې سر دی، وده وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_15.mp3', '', 1761754199, 1761754199),
(36259, 'Ephesians 4:16', 'Ephesians', 4, 16, 'د هغه تر لاس لاندې د بدن ټول غړي د هغو بندونو په وسیله چې د هغو دپاره تیار شوي دي، سره یوځای کوي او نښلوي. کله چې د بدن هر غړی په مناسب ډول خپل کار کوي، نو ټول بدن وده کوي او په مینه خپل ځان جوړوي. په مسیح کې نوی ژوند', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_16.mp3', '', 1761754199, 1761754199),
(36260, 'Ephesians 4:17', 'Ephesians', 4, 17, 'زه تاسو ته د څښتن په نوم دا وایم او په هغې باندې ټینګار کوم چې تاسو باید نور د غیریهودیانو په شان چې په خپلو باطلو خیالونو کې اوسیږي، ژوند ونه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_17.mp3', '', 1761754199, 1761754199),
(36261, 'Ephesians 4:18', 'Ephesians', 4, 18, 'هغوی د خپلو خیالونو په تیارو کې ډوب دي. هغوی د هغه ژوند نه چې خدای یې ورکوي، بې‌برخې شوي دي، ځکه چې هغوی جاهلان او زړونه یې سخت دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_18.mp3', '', 1761754199, 1761754199),
(36262, 'Ephesians 4:19', 'Ephesians', 4, 19, 'هغوی خپل د شرم احساس له لاسه ورکړی او خپل ځانونه یې عیاشۍ ته تسلیم کړي دي او په شوق سره هر ډول ناپاکه کارونه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians4_verse_19.mp3', '', 1761754199, 1761754199),
