(36302, 'Luke 24:27', 'Luke', 24, 27, 'بیا عیسی د موسی د تورات څخه نیولې د ټولو پیغمبرانو تر لیکنو پورې چې د خدای په کلام کې خپله د هغه په هکله لیکل شوي وو، هغوی ته بیان کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_27.mp3', '', 1761754199, 1761754199),
(36303, 'Luke 24:28', 'Luke', 24, 28, 'کله چې دوی د عماوس کلي ته ورنژدې شول، نو عیسی داسې وښودل چې ګوندې هغه نور هم مخکې ځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_28.mp3', '', 1761754199, 1761754199),
(36304, 'Luke 24:29', 'Luke', 24, 29, 'خو هغوی ټینګار وکړ او ویې ویل: «زمونږ سره پاتې شه، ځکه چې ورځ په تېرېدلو ده او ماښام نژدې دی.» نو عیسی کور ته ننوت چې د هغوی سره پاتې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_29.mp3', '', 1761754199, 1761754199),
(36305, 'Luke 24:30', 'Luke', 24, 30, 'کله چې عیسی د هغوی سره دسترخوان ته کښېناست نو ډوډۍ یې راواخیستله، شکر یې پرې وویست، ماته یې کړه او هغوی ته یې ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_30.mp3', '', 1761754199, 1761754199),
(36306, 'Luke 24:31', 'Luke', 24, 31, 'ناڅاپه د هغوی سترګې وغړېدلې او عیسی یې وپېژانده، خو هغه د هغوی د نظر څخه پناه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_31.mp3', '', 1761754199, 1761754199),
(36307, 'Luke 24:32', 'Luke', 24, 32, 'هغوی یو بل ته وویل: «کله چې په لاره کې هغه زمونږ سره خبرې کولې او د خدای د کلام لیکنې یې راته بیانولې، ایا زمونږ زړونه په جوش رانغلل؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_32.mp3', '', 1761754199, 1761754199),
(36308, 'Luke 24:33', 'Luke', 24, 33, 'هغوی سمدلاسه راپاڅېدل او بېرته اورشلیم ته لاړل. هلته یې ولیدل چې یوولس رسولان او نور خلک سره راټول شوي وو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_33.mp3', '', 1761754199, 1761754199),
(36309, 'Luke 24:34', 'Luke', 24, 34, 'او ویل یې چې عیسی په رښتیا راژوندی شوی او شمعون ته ښکاره شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_34.mp3', '', 1761754199, 1761754199),
(36310, 'Luke 24:35', 'Luke', 24, 35, 'نو په لاره کې چې څه شوي وو هغو دواړو شاګردانو هغوی ته بیان کړل او ورته ویې ویل چې څنګه یې عیسی د ډوډۍ ماتولو په وخت کې وپېژانده. عیسی خپلو شاګردانو ته ځان ښکاره کوي (متي ۲۸‏:‌۱۶‌‏-‌۲۰ او مرقوس ۱۶‏:‌۱۴‌‏-‌۱۸ او یوحنا ۲۰‏:‌۱۹‌‏-‌۲۳ او د رسولانو عملونه ۱‏:‌۶‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_35.mp3', '', 1761754199, 1761754199);